from datetime import date, timedelta
import calendar

def recur(start: str, rule: str, count: int) -> list[str]:
    start_date = date.fromisoformat(start)
    tokens = rule.split(' ')
    rtype = tokens[0]
    K = int(tokens[1])

    wd_map = {"MO": 0, "TU": 1, "WE": 2, "TH": 3, "FR": 4, "SA": 5, "SU": 6}
    results = []

    if rtype == "DAILY":
        cur = start_date
        while len(results) < count:
            results.append(cur.isoformat())
            cur += timedelta(days=K)

    elif rtype == "WEEKLY":
        days = [wd_map[d] for d in tokens[2].split(',')]
        # Week 0 Monday
        start_monday = start_date - timedelta(days=start_date.weekday())
        step = 0
        while len(results) < count:
            curr_monday = start_monday + timedelta(weeks=step * K)
            for d in sorted(days):
                candidate = curr_monday + timedelta(days=d)
                if candidate >= start_date:
                    results.append(candidate.isoformat())
                    if len(results) == count:
                        break
            step += 1

    elif rtype == "MONTHLY":
        if len(tokens) == 3:
            # MONTHLY K D
            D = int(tokens[2])
            step = 0
            while len(results) < count:
                total_months = (start_date.year * 12 + (start_date.month - 1)) + step * K
                year = total_months // 12
                month = (total_months % 12) + 1
                _, max_d = calendar.monthrange(year, month)
                target_d = max_d if D == -1 else D
                if 1 <= target_d <= max_d:
                    candidate = date(year, month, target_d)
                    if candidate >= start_date:
                        results.append(candidate.isoformat())
                step += 1
        else:
            # MONTHLY K N WD
            N = int(tokens[2])
            target_wd = wd_map[tokens[3]]
            step = 0
            while len(results) < count:
                total_months = (start_date.year * 12 + (start_date.month - 1)) + step * K
                year = total_months // 12
                month = (total_months % 12) + 1
                _, max_d = calendar.monthrange(year, month)

                matching_days = [
                    d for d in range(1, max_d + 1)
                    if date(year, month, d).weekday() == target_wd
                ]

                target_day = None
                if N == -1:
                    target_day = matching_days[-1]
                elif 1 <= N <= len(matching_days):
                    target_day = matching_days[N - 1]

                if target_day is not None:
                    candidate = date(year, month, target_day)
                    if candidate >= start_date:
                        results.append(candidate.isoformat())
                step += 1

    elif rtype == "YEARLY":
        mm, dd = map(int, tokens[2].split('-'))
        step = 0
        while len(results) < count:
            year = start_date.year + step * K
            try:
                candidate = date(year, mm, dd)
                if candidate >= start_date:
                    results.append(candidate.isoformat())
            except ValueError:
                pass
            step += 1

    return results
